draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw two stick figures
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 - 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W/4 + 30, H/2 + 30);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 - 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 50);
  ctx.lineTo(W - W/4 + 30, H/2 + 30);
  ctx.stroke();

  // draw dynamic connection
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.lineWidth = 2 + 3*Math.abs(Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
